// ============================================================================
// ACTIONS - Command pattern for undo/redo
// ============================================================================
use anyhow::Result;

use crate::game_state::{BuildingType, GameState, ShipType};

pub trait GameAction {
    fn execute(&self, game: &mut GameState) -> Result<()>;
    fn description(&self) -> String;
}

pub struct BuildShipAction {
    pub system_idx: usize,
    pub ship_type: ShipType,
}

impl GameAction for BuildShipAction {
    fn execute(&self, game: &mut GameState) -> Result<()> {
        game.build_ship(self.system_idx, self.ship_type)
    }

    fn description(&self) -> String {
        let (minerals, energy) = self.ship_type.cost();
        format!(
            "Build {} ({} minerals, {} energy)",
            self.ship_type.name(),
            minerals,
            energy
        )
    }
}

pub struct BuildBuildingAction {
    pub system_idx: usize,
    pub building_type: BuildingType,
}

impl GameAction for BuildBuildingAction {
    fn execute(&self, game: &mut GameState) -> Result<()> {
        game.build_building(self.system_idx, self.building_type)
    }

    fn description(&self) -> String {
        let (minerals, energy) = self.building_type.cost();
        format!(
            "Build {} ({} minerals, {} energy)",
            self.building_type.name(),
            minerals,
            energy
        )
    }
}

// ============================================================================
// COMMAND QUEUE V2 - Deferred execution until turn end
// ============================================================================
//
// Design Principle: "Undo until information revealed" (Twilight Imperium style)
//
// Commands are QUEUED but NOT executed until turn end. This means:
// - No dice rolls until commit
// - No card draws until commit
// - No information revealed until commit
// - Perfect undo by just removing from queue
// - Scripts queue sub-commands instead of mutating state
// ============================================================================

use crate::game_state::{
    BuildingType, GameState, HexCoord, LogEntry, PlayerId, Resources, Ship, ShipType,
};

use anyhow::{Result, anyhow, bail};
use serde::{Deserialize, Serialize};

/// Commands represent player intentions - NOT YET EXECUTED
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub enum Command {
    BuildShip {
        system_idx: usize,
        ship_type: ShipType,
    },
    BuildBuilding {
        system_idx: usize,
        building_type: BuildingType,
    },
    MoveShip {
        ship_id: usize,
        destination: HexCoord,
    },
    PlayCard {
        card_idx: usize,
    },
    // Script-generated sub-commands
    SpawnShip {
        ship_type: ShipType,
        location: HexCoord,
        owner: PlayerId,
    },
    ModifyResources {
        minerals: i32,
        energy: i32,
    },
    DrawCards {
        count: usize,
    },
    RepairShips {
        ship_ids: Vec<usize>,
        amount: u32,
    },
    CloakShip {
        ship_id: usize,
        duration: u32,
    },
    DamageShips {
        ship_ids: Vec<usize>,
        damage: u32,
    },
    AddPopulation {
        system_idx: usize,
        amount: u32,
    },
}

impl Command {
    pub fn description(&self, game: &GameState) -> String {
        match self {
            Command::BuildShip {
                ship_type,
                system_idx,
            } => {
                let (minerals, energy) = ship_type.cost();
                let system_name = game
                    .systems
                    .get(*system_idx)
                    .map(|s| s.name.as_str())
                    .unwrap_or("???");
                format!(
                    "Build {} at {} (🔧{} ⚡{})",
                    ship_type.name(),
                    system_name,
                    minerals,
                    energy
                )
            }
            Command::BuildBuilding {
                building_type,
                system_idx,
            } => {
                let (minerals, energy) = building_type.cost();
                let system_name = game
                    .systems
                    .get(*system_idx)
                    .map(|s| s.name.as_str())
                    .unwrap_or("???");
                format!(
                    "Build {} at {} (🔧{} ⚡{})",
                    building_type.name(),
                    system_name,
                    minerals,
                    energy
                )
            }
            Command::MoveShip {
                ship_id,
                destination,
            } => {
                let ship_name = game
                    .ships
                    .iter()
                    .find(|s| s.id == *ship_id)
                    .map(|s| s.ship_type.name())
                    .unwrap_or("Ship");
                format!(
                    "Move {} to ({}, {})",
                    ship_name, destination.q, destination.r
                )
            }
            Command::PlayCard { card_idx } => {
                let card_name = game
                    .cards_hand
                    .get(*card_idx)
                    .map(|c| c.name.as_str())
                    .unwrap_or("Card");
                format!("Play card: {}", card_name)
            }
            Command::SpawnShip {
                ship_type,
                location,
                ..
            } => {
                format!(
                    "Spawn {} at ({}, {})",
                    ship_type.name(),
                    location.q,
                    location.r
                )
            }
            Command::ModifyResources { minerals, energy } => {
                format!("Gain 🔧{:+} ⚡{:+}", minerals, energy)
            }
            Command::DrawCards { count } => {
                format!("Draw {} card(s)", count)
            }
            Command::RepairShips { ship_ids, amount } => {
                format!("Repair {} ship(s) by {} HP", ship_ids.len(), amount)
            }
            Command::CloakShip { ship_id, duration } => {
                let ship_name = game
                    .ships
                    .iter()
                    .find(|s| s.id == *ship_id)
                    .map(|s| s.ship_type.name())
                    .unwrap_or("Ship");
                format!("Cloak {} for {} turns", ship_name, duration)
            }
            Command::DamageShips { ship_ids, damage } => {
                format!("Damage {} ship(s) by {} HP", ship_ids.len(), damage)
            }
            Command::AddPopulation { system_idx, amount } => {
                let system_name = game
                    .systems
                    .get(*system_idx)
                    .map(|s| s.name.as_str())
                    .unwrap_or("???");
                format!("Add {} population to {}", amount, system_name)
            }
        }
    }

    /// Validate against PROJECTED state (queue applied)
    pub fn validate(&self, projected: &ProjectedState, game: &GameState) -> Result<()> {
        match self {
            Command::BuildShip {
                system_idx,
                ship_type,
            } => {
                let system = game
                    .systems
                    .get(*system_idx)
                    .ok_or_else(|| anyhow!("Invalid system index"))?;

                if system.owner != Some(PlayerId::Human) {
                    bail!("You don't own this system");
                }

                let (mineral_cost, energy_cost) = ship_type.cost();
                if projected
                    .resources
                    .get(&PlayerId::Human)
                    .ok_or_else(|| anyhow!("Human player not found."))?
                    .minerals
                    < mineral_cost
                {
                    bail!(
                        "Not enough minerals (need {}, have {} after queue)",
                        mineral_cost,
                        projected
                            .resources
                            .get(&PlayerId::Human)
                            .ok_or_else(|| anyhow!("Human player not found."))?
                            .minerals
                    );
                }
                if projected
                    .resources
                    .get(&PlayerId::Human)
                    .ok_or_else(|| anyhow!("Human player not found."))?
                    .energy
                    < energy_cost
                {
                    bail!(
                        "Not enough energy (need {}, have {} after queue)",
                        energy_cost,
                        projected
                            .resources
                            .get(&PlayerId::Human)
                            .ok_or_else(|| anyhow!("Human player not found."))?
                            .energy
                    );
                }

                Ok(())
            }
            Command::BuildBuilding {
                system_idx,
                building_type,
            } => {
                let system = game
                    .systems
                    .get(*system_idx)
                    .ok_or_else(|| anyhow!("Invalid system index"))?;

                if system.owner != Some(PlayerId::Human) {
                    bail!("You don't own this system");
                }

                let (mineral_cost, energy_cost) = building_type.cost();
                if projected
                    .resources
                    .get(&PlayerId::Human)
                    .ok_or_else(|| anyhow!("Human player not found."))?
                    .minerals
                    < mineral_cost
                {
                    bail!(
                        "Not enough minerals (need {}, have {} after queue)",
                        mineral_cost,
                        projected
                            .resources
                            .get(&PlayerId::Human)
                            .ok_or_else(|| anyhow!("Human player not found."))?
                            .minerals
                    );
                }
                if projected
                    .resources
                    .get(&PlayerId::Human)
                    .ok_or_else(|| anyhow!("Human player not found."))?
                    .energy
                    < energy_cost
                {
                    bail!(
                        "Not enough energy (need {}, have {} after queue)",
                        energy_cost,
                        projected
                            .resources
                            .get(&PlayerId::Human)
                            .ok_or_else(|| anyhow!("Human player not found."))?
                            .energy
                    );
                }

                Ok(())
            }
            Command::MoveShip {
                ship_id,
                destination,
            } => {
                let ship = projected
                    .ships
                    .iter()
                    .find(|s| s.id == *ship_id)
                    .ok_or_else(|| anyhow::anyhow!("Ship not found"))?;

                if ship.owner != PlayerId::Human {
                    bail!("You don't own this ship");
                }

                let distance = ship.location.distance_to(*destination);
                if distance > ship.moves_remaining {
                    bail!(
                        "Not enough movement (need {}, have {} after queue)",
                        distance,
                        ship.moves_remaining
                    );
                }

                if !game.systems.iter().any(|s| s.coord == *destination) {
                    bail!("Invalid destination");
                }

                Ok(())
            }
            Command::PlayCard { card_idx } => {
                let card = game
                    .cards_hand
                    .get(*card_idx)
                    .ok_or_else(|| anyhow::anyhow!("Invalid card index"))?;

                if projected
                    .resources
                    .get(&PlayerId::Human)
                    .ok_or_else(|| anyhow!("Human player not found."))?
                    .minerals
                    < card.cost.minerals
                {
                    bail!(
                        "Not enough minerals (need {}, have {} after queue)",
                        card.cost.minerals,
                        projected
                            .resources
                            .get(&PlayerId::Human)
                            .ok_or_else(|| anyhow!("Human player not found."))?
                            .minerals
                    );
                }
                if projected
                    .resources
                    .get(&PlayerId::Human)
                    .ok_or_else(|| anyhow!("Human player not found."))?
                    .energy
                    < card.cost.energy
                {
                    bail!(
                        "Not enough energy (need {}, have {} after queue)",
                        card.cost.energy,
                        projected
                            .resources
                            .get(&PlayerId::Human)
                            .ok_or_else(|| anyhow!("Human player not found."))?
                            .energy
                    );
                }

                Ok(())
            }
            // Sub-commands don't need validation (generated by validated commands)
            Command::SpawnShip { .. }
            | Command::ModifyResources { .. }
            | Command::DrawCards { .. }
            | Command::RepairShips { .. }
            | Command::CloakShip { .. }
            | Command::DamageShips { .. }
            | Command::AddPopulation { .. } => Ok(()),
        }
    }

    /// Execute this command against actual game state
    /// Returns sub-commands that should also be executed
    pub fn execute(&self, game: &mut GameState) -> Result<Vec<Command>> {
        match self {
            Command::BuildShip {
                system_idx,
                ship_type,
            } => Self::execute_build_ship(game, *system_idx, *ship_type),
            Command::BuildBuilding {
                system_idx,
                building_type,
            } => Self::execute_build_building(game, *system_idx, *building_type),
            Command::MoveShip {
                ship_id,
                destination,
            } => Self::execute_move_ship(game, *ship_id, *destination),
            Command::PlayCard { card_idx } => Self::execute_play_card(game, *card_idx),
            Command::SpawnShip {
                ship_type,
                location,
                owner,
            } => Self::execute_spawn_ship(game, *ship_type, *location, *owner),
            Command::ModifyResources { minerals, energy } => {
                Self::execute_modify_resources(game, *minerals, *energy)
            }
            Command::DrawCards { count } => Self::execute_draw_cards(game, *count),
            Command::RepairShips { ship_ids, amount } => {
                Self::execute_repair_ships(game, ship_ids.clone(), *amount)
            }
            Command::CloakShip { ship_id, duration } => {
                Self::execute_cloak_ship(game, *ship_id, *duration)
            }
            Command::DamageShips { ship_ids, damage } => {
                Self::execute_damage_ships(game, ship_ids.clone(), *damage)
            }
            Command::AddPopulation { system_idx, amount } => {
                Self::execute_add_population(game, *system_idx, *amount)
            }
        }
    }

    fn execute_build_ship(
        game: &mut GameState,
        system_idx: usize,
        ship_type: ShipType,
    ) -> Result<Vec<Command>> {
        let system = &game.systems[system_idx];
        let location = system.coord;
        let system_name = system.name.clone();
        let (mineral_cost, energy_cost) = ship_type.cost();
        let player_resources = game
            .resources
            .get_mut(&PlayerId::Human)
            .ok_or_else(|| anyhow!("Human player not found."))?;

        // Deduct resources
        player_resources.minerals -= mineral_cost;
        player_resources.energy -= energy_cost;

        // Create ship
        let ship_id = game.next_ship_id;
        let ship = Ship::new(ship_id, ship_type, PlayerId::Human, location);
        game.next_ship_id += 1;
        game.ships.push(ship);

        game.action_log.push(LogEntry {
            turn: game.turn,
            player: PlayerId::Human,
            message: format!("Built {} at {}", ship_type.name(), system_name),
        });

        Ok(vec![])
    }

    fn execute_build_building(
        game: &mut GameState,
        system_idx: usize,
        building_type: BuildingType,
    ) -> Result<Vec<Command>> {
        let system = &mut game.systems[system_idx];
        let (mineral_cost, energy_cost) = building_type.cost();
        let system_name = system.name.clone();
        let player_resources = game
            .resources
            .get_mut(&PlayerId::Human)
            .ok_or_else(|| anyhow!("Human player not found."))?;

        // Deduct resources
        player_resources.minerals -= mineral_cost;
        player_resources.energy -= energy_cost;

        // Create building
        system
            .buildings
            .push(crate::game_state::Building { building_type });

        game.action_log.push(LogEntry {
            turn: game.turn,
            player: PlayerId::Human,
            message: format!("Built {} at {}", building_type.name(), system_name),
        });

        Ok(vec![])
    }

    fn execute_move_ship(
        game: &mut GameState,
        ship_id: usize,
        destination: HexCoord,
    ) -> Result<Vec<Command>> {
        let ship_idx = game
            .ships
            .iter()
            .position(|s| s.id == ship_id)
            .ok_or_else(|| anyhow::anyhow!("Ship not found"))?;

        let ship = &mut game.ships[ship_idx];
        let old_location = ship.location;
        let distance = old_location.distance_to(destination);
        let ship_name = ship.ship_type.name();

        ship.location = destination;
        ship.moves_remaining -= distance;

        game.action_log.push(LogEntry {
            turn: game.turn,
            player: PlayerId::Human,
            message: format!(
                "Moved {} from ({},{}) to ({},{})",
                ship_name, old_location.q, old_location.r, destination.q, destination.r
            ),
        });

        // Check for combat - THIS IS WHERE DICE ROLL (at commit time!)
        if let Some(report) = game.check_and_resolve_combat(destination)? {
            game.action_log.push(LogEntry {
                turn: game.turn,
                player: game.current_player,
                message: report.summary(),
            });
        }

        Ok(vec![])
    }

    fn execute_play_card(game: &mut GameState, card_idx: usize) -> Result<Vec<Command>> {
        let card = game.cards_hand.remove(card_idx);
        let player_resources = game
            .resources
            .get_mut(&PlayerId::Human)
            .ok_or_else(|| anyhow!("Human player not found."))?;

        player_resources.minerals -= card.cost.minerals;
        player_resources.energy -= card.cost.energy;

        // Use script engine to generate commands (no legacy approach)
        let script_engine = crate::script_engine::ScriptEngine::new();
        let (_, sub_commands) = script_engine
            .eval_script_with_commands(game, &card.script)
            .map_err(|e| anyhow::anyhow!("Script execution failed: {}", e))?;

        game.action_log.push(LogEntry {
            turn: game.turn,
            player: PlayerId::Human,
            message: format!("Played card: {}", card.name),
        });

        game.cards_discard.push(card);

        Ok(sub_commands)
    }

    fn execute_spawn_ship(
        game: &mut GameState,
        ship_type: ShipType,
        location: HexCoord,
        owner: PlayerId,
    ) -> Result<Vec<Command>> {
        let ship_id = game.next_ship_id;
        let ship = Ship::new(ship_id, ship_type, owner, location);
        game.next_ship_id += 1;
        game.ships.push(ship);

        game.action_log.push(LogEntry {
            turn: game.turn,
            player: owner,
            message: format!(
                "Spawned {} at ({},{})",
                ship_type.name(),
                location.q,
                location.r
            ),
        });

        Ok(vec![])
    }

    fn execute_modify_resources(
        game: &mut GameState,
        minerals: i32,
        energy: i32,
    ) -> Result<Vec<Command>> {
        let player_resources = game
            .resources
            .get_mut(&PlayerId::Human)
            .ok_or_else(|| anyhow!("Human player not found."))?;

        player_resources.minerals = (player_resources.minerals as i32 + minerals).max(0) as u32;
        player_resources.energy = (player_resources.energy as i32 + energy).max(0) as u32;

        if minerals != 0 || energy != 0 {
            game.action_log.push(LogEntry {
                turn: game.turn,
                player: PlayerId::Human,
                message: format!("Resources changed: 🔧{:+} ⚡{:+}", minerals, energy),
            });
        }

        Ok(vec![])
    }

    fn execute_draw_cards(game: &mut GameState, count: usize) -> Result<Vec<Command>> {
        // THIS IS WHERE INFORMATION IS REVEALED (at commit time!)
        game.draw_cards(count);

        game.action_log.push(LogEntry {
            turn: game.turn,
            player: PlayerId::Human,
            message: format!("Drew {} card(s)", count),
        });

        Ok(vec![])
    }

    fn execute_repair_ships(
        game: &mut GameState,
        ship_ids: Vec<usize>,
        amount: u32,
    ) -> Result<Vec<Command>> {
        let mut ships_repaired = 0;

        for ship_id in ship_ids {
            if let Some(ship) = game.ships.iter_mut().find(|s| s.id == ship_id) {
                let old_hp = ship.hp;
                ship.hp = (ship.hp + amount).min(ship.max_hp);
                if ship.hp > old_hp {
                    ships_repaired += 1;
                }
            }
        }

        if ships_repaired > 0 {
            game.action_log.push(LogEntry {
                turn: game.turn,
                player: PlayerId::Human,
                message: format!("Repaired {} ships by {} HP", ships_repaired, amount),
            });
        }

        Ok(vec![])
    }

    fn execute_cloak_ship(
        game: &mut GameState,
        ship_id: usize,
        duration: u32,
    ) -> Result<Vec<Command>> {
        // For now, just log the cloaking - actual cloaking mechanics would need ship state changes
        if let Some(ship) = game.ships.iter().find(|s| s.id == ship_id) {
            game.action_log.push(LogEntry {
                turn: game.turn,
                player: PlayerId::Human,
                message: format!("Cloaked {} for {} turns", ship.ship_type.name(), duration),
            });
        }

        Ok(vec![])
    }

    fn execute_damage_ships(
        game: &mut GameState,
        ship_ids: Vec<usize>,
        damage: u32,
    ) -> Result<Vec<Command>> {
        let mut ships_damaged = 0;

        for ship_id in ship_ids {
            if let Some(ship) = game.ships.iter_mut().find(|s| s.id == ship_id) {
                if ship.hp > damage {
                    ship.hp -= damage;
                    ships_damaged += 1;
                } else {
                    ship.hp = 0;
                    ships_damaged += 1;
                    // Ship would be destroyed here - would need more complex logic
                }
            }
        }

        if ships_damaged > 0 {
            game.action_log.push(LogEntry {
                turn: game.turn,
                player: PlayerId::Human,
                message: format!("Damaged {} ships by {} HP", ships_damaged, damage),
            });
        }

        Ok(vec![])
    }

    fn execute_add_population(
        game: &mut GameState,
        system_idx: usize,
        amount: u32,
    ) -> Result<Vec<Command>> {
        if let Some(system) = game.systems.get_mut(system_idx) {
            system.population += amount;

            game.action_log.push(LogEntry {
                turn: game.turn,
                player: PlayerId::Human,
                message: format!("Added {} population to {}", amount, system.name),
            });
        }

        Ok(vec![])
    }
}

/// The command queue - now with deferred execution
#[derive(Clone, Debug, Default)]
pub struct CommandQueue {
    pub pending: Vec<Command>,
}

impl CommandQueue {
    pub fn new() -> Self {
        Self {
            pending: Vec::new(),
        }
    }

    /// Get pending count without needing game state
    pub fn pending_count(&self) -> usize {
        self.pending.len()
    }

    /// Get the pending commands for inspection
    pub fn pending(&self) -> &[Command] {
        &self.pending
    }
}

/// Projected state for command validation - represents game state after queue is applied
#[derive(Clone, Debug, Default)]
pub struct ProjectedState {
    pub resources: std::collections::HashMap<PlayerId, Resources>,
    pub ships: Vec<Ship>,
}

impl ProjectedState {
    pub fn from_game_and_queue(game: &GameState, queue: &[Command]) -> Result<Self> {
        let mut resources = game.resources.clone();
        let mut ships = game.ships.clone();

        // Apply queue to resources and ships
        for command in queue {
            match command {
                Command::BuildShip {
                    system_idx: _,
                    ship_type,
                } => {
                    let (mineral_cost, energy_cost) = ship_type.cost();
                    // Get player resources for the human player
                    let player_resources = resources
                        .get_mut(&PlayerId::Human)
                        .ok_or_else(|| anyhow!("Human player not found."))?;
                    player_resources.minerals -= mineral_cost;
                    player_resources.energy -= energy_cost;
                }
                Command::BuildBuilding {
                    system_idx: _,
                    building_type,
                } => {
                    let (mineral_cost, energy_cost) = building_type.cost();
                    // Get player resources for the human player
                    let player_resources = resources
                        .get_mut(&PlayerId::Human)
                        .ok_or_else(|| anyhow!("Human player not found."))?;
                    player_resources.minerals -= mineral_cost;
                    player_resources.energy -= energy_cost;
                }
                Command::PlayCard { card_idx: _ } => {
                    // Card costs are already deducted when played, so we don't need to process here
                }
                Command::MoveShip {
                    ship_id,
                    destination: _,
                } => {
                    // Move doesn't affect resources but does affect ship locations and movement
                    if let Some(_ship) = ships.iter_mut().find(|s| s.id == *ship_id) {
                        // Movement is handled by the command execution, not by the projected state
                        // Here we just update the projected state for validation purposes
                        // But since the movement is handled by actual game state, we don't need to
                        // make changes to the projected ships
                    }
                }
                Command::SpawnShip {
                    ship_type: _,
                    location: _,
                    owner: _,
                } => {
                    // Spawn doesn't affect resources
                }
                Command::ModifyResources { minerals, energy } => {
                    // Get player resources for the human player
                    let player_resources = resources
                        .get_mut(&PlayerId::Human)
                        .ok_or_else(|| anyhow!("Human player not found."))?;
                    player_resources.minerals =
                        (player_resources.minerals as i32 + *minerals).max(0) as u32;
                    player_resources.energy =
                        (player_resources.energy as i32 + *energy).max(0) as u32;
                }
                Command::DrawCards { count: _ } => {
                    // Draw cards don't affect resources directly in this context
                }
                Command::RepairShips { .. } => {
                    // Repair doesn't affect resources directly in this context
                }
                Command::CloakShip { .. } => {
                    // Cloak doesn't affect resources directly in this context
                }
                Command::DamageShips { .. } => {
                    // Damage doesn't affect resources directly in this context
                }
                Command::AddPopulation { .. } => {
                    // Add population doesn't affect resources directly in this context
                }
            }
        }

        Ok(ProjectedState { resources, ships })
    }
}

// Separate functions that work with GameState to avoid borrow checker issues
impl GameState {
    /// Queue a command (NO execution yet!)
    fn queue_command_internal(&mut self, command: Command) -> Result<String> {
        // Validate against projected state
        let projected = ProjectedState::from_game_and_queue(self, &self.command_queue.pending);
        command.validate(&projected?, self)?;

        let description = command.description(self);
        self.command_queue.pending.push(command);

        Ok(description)
    }

    /// Remove last command (perfect undo - nothing was executed!)
    fn undo_last_command_internal(&mut self) -> Result<String> {
        let command = self
            .command_queue
            .pending
            .pop()
            .ok_or_else(|| anyhow::anyhow!("No commands to undo"))?;

        Ok(format!("Undid: {}", command.description(self)))
    }

    /// Execute all pending commands
    fn commit_commands_internal(&mut self) {
        let mut commands_to_execute = self.command_queue.pending.clone();
        self.command_queue.pending.clear();

        while !commands_to_execute.is_empty() {
            let command = commands_to_execute.remove(0);
            let sub_commands = command.execute(self).unwrap();

            // Add sub-commands to front of queue (execute them next)
            for sub_cmd in sub_commands.into_iter().rev() {
                commands_to_execute.insert(0, sub_cmd);
            }
        }
    }

    /// Get list of pending commands for display
    fn pending_commands_internal(&self) -> Vec<String> {
        self.command_queue
            .pending
            .iter()
            .map(|cmd| cmd.description(self))
            .collect()
    }

    /// Get projected state for UI preview
    fn projected_state_internal(&self) -> ProjectedState {
        ProjectedState::from_game_and_queue(self, &self.command_queue.pending)
            .expect("Could not create ProjectedState")
    }
}

