// ============================================================================
// SCRIPT ENGINE - Rhai scripting for cards and console
// ============================================================================

use crate::command_queue::Command;
use crate::game_state::{GameState, HexCoord, PlayerId, Ship, ShipType};
use rhai::{Engine, EvalAltResult, Scope};

use anyhow::{Result, anyhow};

/// Command queue API for Rhai scripts
#[derive(Debug, Clone)]
pub struct ScriptCommandQueue {
    commands: Vec<Command>,
}

impl ScriptCommandQueue {
    pub fn new() -> Self {
        Self {
            commands: Vec::new(),
        }
    }

    pub fn add_command(&mut self, command: Command) {
        self.commands.push(command);
    }

    pub fn take_commands(&mut self) -> Vec<Command> {
        std::mem::take(&mut self.commands)
    }
}

impl Default for ScriptCommandQueue {
    fn default() -> Self {
        Self::new()
    }
}

pub struct ScriptEngine {
    engine: Engine,
}

impl ScriptEngine {
    pub fn new() -> Self {
        let mut engine = Engine::new();

        // Register command queue functions once
        engine.register_fn(
            "modify_resources",
            |cmd_queue: &mut ScriptCommandQueue, minerals: i32, energy: i32| {
                cmd_queue.add_command(Command::ModifyResources { minerals, energy });
            },
        );

        engine.register_fn(
            "spawn_ship",
            |cmd_queue: &mut ScriptCommandQueue,
             ship_type_str: &str,
             q: i32,
             r: i32,
             owner: i64| {
                let ship_type = match ship_type_str {
                    "Fighter" => ShipType::Fighter,
                    "Destroyer" => ShipType::Destroyer,
                    "Scout" => ShipType::Scout,
                    "Battleship" => ShipType::Battleship,
                    "ColonyShip" => ShipType::ColonyShip,
                    _ => return, // Or return an error (needs Rhai error handling)
                };
                let owner_id = if owner == 0 {
                    PlayerId::Human
                } else {
                    PlayerId::AI(owner as u8)
                };
                cmd_queue.add_command(Command::SpawnShip {
                    ship_type,
                    location: HexCoord::new(q, r),
                    owner: owner_id,
                });
            },
        );

        engine.register_fn(
            "repair_ships",
            |cmd_queue: &mut ScriptCommandQueue, amount: u32| {
                // This would need ship selection logic - for now repair all human ships
                cmd_queue.add_command(Command::RepairShips {
                    ship_ids: vec![], // Will be filled by the calling context
                    amount,
                });
            },
        );

        engine.register_fn(
            "draw_cards",
            |cmd_queue: &mut ScriptCommandQueue, count: usize| {
                cmd_queue.add_command(Command::DrawCards { count });
            },
        );

        engine.register_fn(
            "add_population",
            |cmd_queue: &mut ScriptCommandQueue, system_idx: usize, amount: u32| {
                cmd_queue.add_command(Command::AddPopulation { system_idx, amount });
            },
        );

        engine.register_type_with_name::<ScriptCommandQueue>("CommandQueue");
        engine.register_type_with_name::<Vec<i64>>("ShipIdList");

        engine.register_fn("select_ships", |ships: &Vec<ShipSnapshot>, owner: i64| {
            ships
                .iter()
                .filter(|s| s.owner == owner)
                .map(|s| s.id)
                .collect::<Vec<i64>>()
        });

        Self { engine }
    }

    /// Evaluate a script that generates commands instead of modifying state directly
    pub fn eval_script_with_commands(
        &self,
        game: &GameState,
        script: &str,
    ) -> Result<(String, Vec<Command>)> {
        let mut scope = Scope::new();
        let commands = Vec::new();
        let player_resources = game
            .resources
            .get(&PlayerId::Human)
            .ok_or(anyhow!("Human player not found!"))?;

        // Push primitive game state values (read-only)
        scope.push_constant("Player_Human", 0i64);
        scope.push_constant("Player_AI", 1i64);
        scope.push("turn", game.turn as i64);
        scope.push("energy", player_resources.energy as i64);
        scope.push("minerals", player_resources.minerals as i64);

        // Create snapshots for collections (read-only)
        let ships_snapshot: Vec<ShipSnapshot> =
            game.ships.iter().map(ShipSnapshot::from_ship).collect();
        scope.push("ships", ships_snapshot);

        // Execute the script using Rhai's built-in evaluation
        // The script should use the registered functions instead of string parsing
        let result: Result<String, Box<EvalAltResult>> = self.engine.eval::<String>(&script);
        let result_str = match result {
            Ok(val) => val,
            Err(err) => {
                // Log the error but don't fail - return empty command list
                eprintln!("Script evaluation error: {}", err);
                return Ok((format!("Script error: {}", err), Vec::new()));
            }
        };

        // We now rely on the Rhai script to call the registered functions directly
        // These functions (modify_resources, spawn_ship, etc.) are already registered and will
        // populate the command queue through the ScriptCommandQueue passed to them

        Ok((result_str, commands))
    }

    /// Play a card using command queue - generates commands instead of modifying state directly
    pub fn play_card_with_commands(
        &self,
        game: &GameState,
        card_idx: usize,
    ) -> Result<(String, Vec<Command>)> {
        let human_res = game
            .resources
            .get(&PlayerId::Human)
            .ok_or(anyhow!("Human resources missing"))?;

        let card = &game.cards_hand[card_idx];
        if human_res.minerals < card.cost.minerals {
            return Err(anyhow!("Not enough minerals (need {})", card.cost.minerals));
        }
        if human_res.energy < card.cost.energy {
            return Err(anyhow!("Not enough energy (need {})", card.cost.energy));
        }

        // Execute card script to generate commands
        let (result, commands) = self.eval_script_with_commands(game, &card.script)?;

        Ok((result, commands))
    }
}

impl Default for ScriptEngine {
    fn default() -> Self {
        Self::new()
    }
}

// ============================================================================
// SHIP SNAPSHOT - Rhai-compatible ship data
// ============================================================================

#[derive(Debug, Clone)]
pub struct ShipSnapshot {
    pub id: i64,
    pub owner: i64, // 0 = Human, 1+ = AI
    pub hp: i64,
    pub max_hp: i64,
    pub moves_remaining: i64,
    pub location_q: i64,
    pub location_r: i64,
}

impl ShipSnapshot {
    pub fn from_ship(ship: &Ship) -> Self {
        Self {
            id: ship.id as i64,
            owner: match ship.owner {
                PlayerId::Human => 0,
                PlayerId::AI(n) => n as i64,
            },
            hp: ship.hp as i64,
            max_hp: ship.max_hp as i64, // Fixed: now uses actual max_hp field
            moves_remaining: ship.moves_remaining as i64,
            location_q: ship.location.q as i64,
            location_r: ship.location.r as i64,
        }
    }
}

// ============================================================================
// HEX RENDERING - Canvas-based hex grid using Ratatui's Canvas widget
// ============================================================================

use crate::game_state::{HexCoord, PlayerId};
use ratatui::{style::Color, widgets::canvas::Line as CanvasLine};

/// Hexagon shape for Canvas rendering using proper Line shapes
pub struct Hexagon {
    pub center_x: f64,
    pub center_y: f64,
    pub size: f64,
    pub color: Color,
    pub owner: Option<PlayerId>,
}

type CoordPair = (f64, f64);

impl Hexagon {
    pub fn new(
        center_x: f64,
        center_y: f64,
        size: f64,
        color: Color,
        owner: Option<PlayerId>,
    ) -> Self {
        Self {
            center_x,
            center_y,
            size,
            color,
            owner,
        }
    }

    /// Calculate the 6 vertices of a flat-top hexagon
    /// Flat-top means two vertices point left/right
    fn vertices(&self) -> [(f64, f64); 6] {
        // For flat-top, vertices are at angles: 0°, 60°, 120°, 180°, 240°, 300°
        let mut verts = [(0.0, 0.0); 6];

        for (i, item) in verts.iter_mut().enumerate() {
            let angle_deg = 60.0 * i as f64;
            let angle_rad = angle_deg.to_radians();
            *item = (
                self.center_x + self.size * angle_rad.cos(),
                self.center_y + self.size * angle_rad.sin(),
            );
        }

        verts
    }

    pub fn lines(&self) -> Vec<CanvasLine> {
        let verts = self.vertices();
        let mut offset_verts = verts;
        offset_verts.rotate_left(1);
        let vert_pairs: Vec<(&CoordPair, &CoordPair)> =
            verts.iter().zip(offset_verts.iter()).collect::<Vec<_>>();

        let mut lines = Vec::new();
        for ((x1, y1), (x2, y2)) in vert_pairs.iter() {
            lines.push(CanvasLine {
                x1: *x1,
                y1: *y1,
                x2: *x2,
                y2: *y2,
                color: self.color,
            })
        }
        lines
    }
}

/// Convert axial hex coordinates to world space (x, y)
/// Using flat-top orientation
pub fn axial_to_world(coord: HexCoord, hex_size: f64) -> (f64, f64) {
    // For flat-top hexagons:
    // x = size * (3/2 * q)
    // y = size * (sqrt(3)/2 * q + sqrt(3) * r)

    let x = hex_size * 1.5 * coord.q as f64;
    let y = hex_size * (3.0_f64.sqrt() / 2.0 * coord.q as f64 + 3.0_f64.sqrt() * coord.r as f64);

    (x, y)
}

/// A tile to render in a hex cell
#[derive(Debug, Clone)]
pub struct HexTile {
    /// Owner of this tile
    pub owner: Option<PlayerId>,
    /// Color for this tile
    pub color: Color,
}

impl HexTile {
    pub fn new(owner: Option<PlayerId>, color: Color) -> Self {
        Self { owner, color }
    }
}

