// ============================================================================
// RULE SYSTEM - Declarative game rules
// ============================================================================

use crate::game_state::{Cost, GameState, PlayerId};
use anyhow::{Result, bail};

/// A condition that can be checked against game state
pub trait Condition {
    fn check(&self, game: &GameState) -> Result<()>;
    fn description(&self) -> String;
}

/// A requirement for playing a card or taking an action
pub struct Requirement {
    conditions: Vec<Box<dyn Condition>>,
}

impl Requirement {
    fn check_all(&self, game: &GameState) -> Result<()> {
        for condition in &self.conditions {
            condition.check(game)?;
        }
        Ok(())
    }
}

// Concrete conditions
pub struct OwnsSystem {
    system_idx: usize,
    player: PlayerId,
}

impl Condition for OwnsSystem {
    fn check(&self, game: &GameState) -> Result<()> {
        match game.systems.get(self.system_idx) {
            Some(sys) if sys.owner == Some(self.player) => Ok(()),
            Some(_) => bail!("You don't own this system"),
            None => bail!("Invalid system"),
        }
    }

    fn description(&self) -> String {
        "Must own system".to_string()
    }
}

pub struct HasResources {
    minerals: u32,
    energy: u32,
}

impl Condition for HasResources {
    fn check(&self, game: &GameState) -> Result<()> {
        // For now, assume we're checking resources for the current player
        // This might need to be updated to accept a player parameter
        let current_player = game.current_player;
        if let Some(player_resources) = game.resources.get(&current_player) {
            if player_resources.minerals < self.minerals {
                bail!("Need {} minerals", self.minerals);
            }
            if player_resources.energy < self.energy {
                bail!("Need {} energy", self.energy);
            }
        } else {
            bail!("No resources found for current player");
        }
        Ok(())
    }

    fn description(&self) -> String {
        format!("Cost: {} minerals, {} energy", self.minerals, self.energy)
    }
}

pub struct ShipCanMove {
    ship_id: usize,
}

impl Condition for ShipCanMove {
    fn check(&self, game: &GameState) -> Result<()> {
        let ship = game
            .ships
            .iter()
            .find(|s| s.id == self.ship_id)
            .ok_or_else(|| anyhow::anyhow!("Ship not found"))?;

        if ship.moves_remaining == 0 {
            bail!("Ship has no movement left");
        }

        Ok(())
    }

    fn description(&self) -> String {
        "Ship must have movement remaining".to_string()
    }
}

// Composite conditions (AND/OR/NOT)
pub struct AllOf {
    conditions: Vec<Box<dyn Condition>>,
}

impl Condition for AllOf {
    fn check(&self, game: &GameState) -> Result<()> {
        for cond in &self.conditions {
            cond.check(game)?;
        }
        Ok(())
    }

    fn description(&self) -> String {
        let descs: Vec<_> = self.conditions.iter().map(|c| c.description()).collect();
        descs.join(" AND ")
    }
}

pub struct AnyOf {
    conditions: Vec<Box<dyn Condition>>,
}

impl Condition for AnyOf {
    fn check(&self, game: &GameState) -> Result<()> {
        let mut errors = Vec::new();

        for cond in &self.conditions {
            match cond.check(game) {
                Ok(_) => return Ok(()),
                Err(e) => errors.push(e.to_string()),
            }
        }

        bail!("None of the conditions met: {}", errors.join(", "))
    }

    fn description(&self) -> String {
        let descs: Vec<_> = self.conditions.iter().map(|c| c.description()).collect();
        descs.join(" OR ")
    }
}

// ============================================================================
// Example usage functions
// ============================================================================

/// Example usage: Check if player can play a card
pub fn can_play_card(
    game: &GameState,
    _player: PlayerId,
    minerals: u32,
    energy: u32,
) -> Result<()> {
    let requirement = Requirement {
        conditions: vec![Box::new(HasResources { minerals, energy })],
    };

    requirement.check_all(game)
}

/// Example: Check if player can build a ship at a system
pub fn can_build_ship_at_system(
    game: &GameState,
    system_idx: usize,
    player: PlayerId,
    ship_cost: Cost,
) -> Result<()> {
    let requirement = Requirement {
        conditions: vec![
            Box::new(OwnsSystem { system_idx, player }),
            Box::new(HasResources {
                minerals: ship_cost.minerals,
                energy: ship_cost.energy,
            }),
        ],
    };

    requirement.check_all(game)
}

// ============================================================================
// Victory Conditions
// ============================================================================

pub trait VictoryCondition {
    fn check(&self, game: &GameState) -> Option<PlayerId>;
    fn description(&self) -> String;
    fn progress(&self, game: &GameState, player: PlayerId) -> String;
}

/// Win by controlling a certain number of systems
pub struct DominationVictory {
    pub required_systems: usize,
}

impl VictoryCondition for DominationVictory {
    fn check(&self, game: &GameState) -> Option<PlayerId> {
        // Check all players
        for player in [PlayerId::Human, PlayerId::AI(1), PlayerId::AI(2)] {
            let owned = game
                .systems
                .iter()
                .filter(|s| s.owner == Some(player))
                .count();

            if owned >= self.required_systems {
                return Some(player);
            }
        }
        None
    }

    fn description(&self) -> String {
        format!("Control {} star systems", self.required_systems)
    }

    fn progress(&self, game: &GameState, player: PlayerId) -> String {
        let owned = game
            .systems
            .iter()
            .filter(|s| s.owner == Some(player))
            .count();
        format!("{}/{} systems controlled", owned, self.required_systems)
    }
}

/// Win by achieving a certain total fleet combat strength
pub struct MilitaryVictory {
    pub required_strength: u32,
}

impl VictoryCondition for MilitaryVictory {
    fn check(&self, game: &GameState) -> Option<PlayerId> {
        for player in [PlayerId::Human, PlayerId::AI(1), PlayerId::AI(2)] {
            let strength: u32 = game
                .ships
                .iter()
                .filter(|s| s.owner == player)
                .map(|s| s.ship_type.combat_strength())
                .sum();

            if strength >= self.required_strength {
                return Some(player);
            }
        }
        None
    }

    fn description(&self) -> String {
        format!(
            "Build a fleet with {} total combat strength",
            self.required_strength
        )
    }

    fn progress(&self, game: &GameState, player: PlayerId) -> String {
        let strength: u32 = game
            .ships
            .iter()
            .filter(|s| s.owner == player)
            .map(|s| s.ship_type.combat_strength())
            .sum();
        format!("{}/{} fleet strength", strength, self.required_strength)
    }
}

/// Win by eliminating all other players (total conquest)
pub struct ConquestVictory;

impl VictoryCondition for ConquestVictory {
    fn check(&self, game: &GameState) -> Option<PlayerId> {
        // Find all players who own at least one system
        let players_with_systems: Vec<PlayerId> = game
            .systems
            .iter()
            .filter_map(|s| s.owner)
            .collect::<std::collections::HashSet<_>>()
            .into_iter()
            .collect();

        // Victory if only one player remains
        if players_with_systems.len() == 1 {
            players_with_systems.first().copied()
        } else {
            None
        }
    }

    fn description(&self) -> String {
        "Eliminate all other factions".to_string()
    }

    fn progress(&self, game: &GameState, player: PlayerId) -> String {
        let owned = game
            .systems
            .iter()
            .filter(|s| s.owner == Some(player))
            .count();
        let total = game.systems.len();
        format!("{}/{} systems (conquest)", owned, total)
    }
}

/// Helper function to check all victory conditions
pub fn check_victory(game: &GameState) -> Option<(PlayerId, String)> {
    let conditions: Vec<Box<dyn VictoryCondition>> = vec![
        Box::new(DominationVictory {
            required_systems: 12,
        }),
        Box::new(MilitaryVictory {
            required_strength: 50,
        }),
        Box::new(ConquestVictory),
    ];

    for condition in conditions {
        if let Some(winner) = condition.check(game) {
            return Some((winner, condition.description()));
        }
    }

    None
}

