// GALAXY GENERATION - Procedural galaxy creation
// ============================================================================

use crate::game_state::{HexCoord, PlayerId, StarSystem};
use rand::{Rng, SeedableRng};
use std::collections::HashSet;

#[derive(Debug, Clone)]
pub struct GalaxySettings {
    pub size: GalaxySize,
    pub num_ai_players: usize,
    pub layout: GalaxyLayout,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum GalaxySize {
    Small,  // ~12 systems
    Medium, // ~18 systems (default)
    Large,  // ~24 systems
    Huge,   // ~36 systems
}

impl GalaxySize {
    pub fn system_count(&self) -> usize {
        match self {
            GalaxySize::Small => 12,
            GalaxySize::Medium => 18,
            GalaxySize::Large => 24,
            GalaxySize::Huge => 36,
        }
    }

    pub fn radius(&self) -> i32 {
        match self {
            GalaxySize::Small => 2,
            GalaxySize::Medium => 2,
            GalaxySize::Large => 3,
            GalaxySize::Huge => 4,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum GalaxyLayout {
    Clustered, // Systems near each other
    Scattered, // Systems spread out
    Ring,      // Systems in rings around center
    Spiral,    // Spiral arm pattern
}

impl Default for GalaxySettings {
    fn default() -> Self {
        Self {
            size: GalaxySize::Medium,
            num_ai_players: 2,
            layout: GalaxyLayout::Clustered,
        }
    }
}

/// Generate a random galaxy based on settings
pub fn generate_galaxy(
    mut systems: Vec<StarSystem>,
    settings: &GalaxySettings,
    seed: u64,
) -> Vec<StarSystem> {
    let mut rng = rand::rngs::StdRng::seed_from_u64(seed);

    // Limit systems to desired count
    if systems.len() > settings.size.system_count() {
        systems.truncate(settings.size.system_count());
    }

    // Generate coordinates based on layout
    let coords = generate_coordinates(settings, seed);

    // Assign coordinates to systems
    for (system, coord) in systems.iter_mut().zip(coords.iter()) {
        system.coord = *coord;
        system.owner = None; // Clear all ownership
    }

    // Assign starting systems to players
    assign_starting_systems(&mut systems, settings, &mut rng);

    systems
}

/// Generate hex coordinates based on galaxy layout
fn generate_coordinates(settings: &GalaxySettings, seed: u64) -> Vec<HexCoord> {
    let mut coords = HashSet::new();
    let radius = settings.size.radius();

    match settings.layout {
        GalaxyLayout::Clustered => {
            // Fill rings from center outward
            for r in 0..=radius {
                coords.extend(hex_ring(0, 0, r));
            }
        }
        GalaxyLayout::Scattered => {
            // Random positions within radius
            let mut rng = rand::rngs::StdRng::seed_from_u64(seed);
            while coords.len() < settings.size.system_count() {
                let q = rng.random_range(-radius..=radius);
                let r = rng.random_range(-radius..=radius);
                let s = -q - r;

                // Check cube constraint: |q| + |r| + |s| <= radius * 2
                if q.abs() + r.abs() + s.abs() <= radius * 2 {
                    coords.insert(HexCoord::new(q, r));
                }
            }
        }
        GalaxyLayout::Ring => {
            // Systems in concentric rings
            coords.insert(HexCoord::new(0, 0)); // Center
            for ring in 1..=radius {
                coords.extend(hex_ring(0, 0, ring));
            }
        }
        GalaxyLayout::Spiral => {
            // Spiral arm pattern
            coords.insert(HexCoord::new(0, 0));

            let arms = 3;
            let points_per_arm = settings.size.system_count() / arms;

            for arm in 0..arms {
                let angle_offset = (arm as f64) * (2.0 * std::f64::consts::PI / arms as f64);

                for i in 1..=points_per_arm {
                    let distance = (i as f64).sqrt() * 1.5;
                    let angle = angle_offset + (i as f64) * 0.3;

                    let q = (distance * angle.cos()).round() as i32;
                    let r = (distance * angle.sin()).round() as i32;

                    coords.insert(HexCoord::new(q, r));
                }
            }
        }
    }

    // Convert to Vec and truncate to desired size
    let mut coord_vec: Vec<HexCoord> = coords.into_iter().collect();
    coord_vec.truncate(settings.size.system_count());
    coord_vec
}

/// Generate all hexes in a ring at given distance from center
fn hex_ring(center_q: i32, center_r: i32, radius: i32) -> Vec<HexCoord> {
    if radius == 0 {
        return vec![HexCoord::new(center_q, center_r)];
    }

    let mut results = Vec::new();

    // Start at one corner of the hex
    let mut q = center_q - radius;
    let mut r = center_r + radius;

    // Walk around the six sides
    let directions = [
        (1, 0),  // East
        (1, -1), // Southeast
        (0, -1), // Southwest
        (-1, 0), // West
        (-1, 1), // Northwest
        (0, 1),  // Northeast
    ];

    for (dq, dr) in directions {
        for _ in 0..radius {
            results.push(HexCoord::new(q, r));
            q += dq;
            r += dr;
        }
    }

    results
}

/// Assign starting systems to players
fn assign_starting_systems(
    systems: &mut [StarSystem],
    settings: &GalaxySettings,
    rng: &mut impl Rng,
) {
    if systems.is_empty() {
        return;
    }

    // Create list of all players
    let mut players = vec![PlayerId::Human];
    for i in 1..=settings.num_ai_players {
        players.push(PlayerId::AI(i as u8));
    }

    // Find systems that are far apart for starting positions
    let starting_indices = find_distant_systems(systems, players.len(), rng);

    // Assign one system to each player
    for (player, &idx) in players.iter().zip(starting_indices.iter()) {
        if let Some(system) = systems.get_mut(idx) {
            system.owner = Some(*player);
            system.population = 100;
            system.production = 50;
        }
    }
}

/// Find N systems that are maximally distant from each other
fn find_distant_systems(systems: &[StarSystem], count: usize, rng: &mut impl Rng) -> Vec<usize> {
    if systems.len() <= count {
        return (0..systems.len()).collect();
    }

    let mut selected = Vec::new();

    // Pick first system randomly
    selected.push(rng.random_range(0..systems.len()));

    // For each subsequent system, pick the one farthest from all selected
    while selected.len() < count {
        let mut best_idx = 0;
        let mut best_min_distance = 0;

        for (idx, system) in systems.iter().enumerate() {
            if selected.contains(&idx) {
                continue;
            }

            // Find minimum distance to any selected system
            let min_distance = selected
                .iter()
                .map(|&sel_idx| system.coord.distance_to(systems[sel_idx].coord))
                .min()
                .unwrap_or(0);

            if min_distance > best_min_distance {
                best_min_distance = min_distance;
                best_idx = idx;
            }
        }

        selected.push(best_idx);
    }

    selected
}

/// Get human-readable name for galaxy size
impl GalaxySize {
    pub fn name(&self) -> &'static str {
        match self {
            GalaxySize::Small => "Small",
            GalaxySize::Medium => "Medium",
            GalaxySize::Large => "Large",
            GalaxySize::Huge => "Huge",
        }
    }
}

/// Get human-readable name for galaxy layout
impl GalaxyLayout {
    pub fn name(&self) -> &'static str {
        match self {
            GalaxyLayout::Clustered => "Clustered",
            GalaxyLayout::Scattered => "Scattered",
            GalaxyLayout::Ring => "Ring",
            GalaxyLayout::Spiral => "Spiral",
        }
    }
}

// ============================================================================
// COMBAT - Ship combat system with dice rolling
// ============================================================================

use crate::game_state::{GameState, HexCoord, LogEntry, PlayerId, Ship, ShipType};
use anyhow::{Context, Result, bail};
use rand::Rng;
use std::collections::HashSet;

#[derive(Debug, Clone)]
pub struct CombatRoll {
    pub attacker_damage: u32,
    pub defender_damage: u32,
    pub attacker_hits: u32,
    pub defender_hits: u32,
}

#[derive(Debug, Clone)]
pub struct ShipInfo {
    pub id: usize,
    pub ship_type: ShipType,
    pub hp: u32,
    pub max_hp: u32,
}

impl ShipInfo {
    pub fn from_ship(ship: &Ship) -> Self {
        Self {
            id: ship.id,
            ship_type: ship.ship_type,
            hp: ship.hp,
            max_hp: ship.max_hp,
        }
    }
}

#[derive(Debug)]
pub struct CombatReport {
    pub location: HexCoord,
    pub attacker: PlayerId,
    pub defender: PlayerId,
    pub attacker_strength: u32,
    pub defender_strength: u32,
    pub roll: CombatRoll,
    pub attacker_casualties: Vec<String>,
    pub defender_casualties: Vec<String>,
    pub attacker_survivors: Vec<ShipInfo>,
    pub defender_survivors: Vec<ShipInfo>,
}

impl CombatReport {
    pub fn summary(&self) -> String {
        format!(
            "Combat at ({},{}): {} vs {}\n\
             Attacker: {} strength, {} hits → {} casualties\n\
             Defender: {} strength, {} hits → {} casualties",
            self.location.q,
            self.location.r,
            self.attacker,
            self.defender,
            self.attacker_strength,
            self.roll.attacker_hits,
            if self.attacker_casualties.is_empty() {
                "None".to_string()
            } else {
                self.attacker_casualties.join(", ")
            },
            self.defender_strength,
            self.roll.defender_hits,
            if self.defender_casualties.is_empty() {
                "None".to_string()
            } else {
                self.defender_casualties.join(", ")
            },
        )
    }
}

impl GameState {
    /// Check for combat at a location and resolve if multiple factions present
    /// Returns Some(report) if combat occurred, None otherwise
    pub fn check_and_resolve_combat(&mut self, location: HexCoord) -> Result<Option<CombatReport>> {
        let factions = self.get_factions_at_location(location);

        if factions.len() < 2 {
            return Ok(None); // No combat - only one faction present
        }

        // Current player attacks first faction they encounter
        if !factions.contains(&self.current_player) {
            // Current player not involved - no auto-combat for AI vs AI (for now)
            return Ok(None);
        }

        // Find first enemy
        let defender = factions
            .iter()
            .find(|&&p| p != self.current_player)
            .copied()
            .context("No enemy found despite multiple factions")?;

        let report = self.resolve_combat_between(location, self.current_player, defender)?;
        Ok(Some(report))
    }

    /// Get all factions with ships at a location
    fn get_factions_at_location(&self, location: HexCoord) -> HashSet<PlayerId> {
        self.ships
            .iter()
            .filter(|s| s.location == location)
            .map(|s| s.owner)
            .collect()
    }

    /// Get valid attack targets for current player at location
    pub fn valid_attack_targets(&self, location: HexCoord) -> Vec<PlayerId> {
        let has_own_ships = self
            .ships
            .iter()
            .any(|s| s.location == location && s.owner == self.current_player);

        if !has_own_ships {
            return Vec::new();
        }

        self.get_factions_at_location(location)
            .into_iter()
            .filter(|&p| p != self.current_player)
            .collect()
    }

    /// Initiate an attack at a location against a specific target
    pub fn attack_at(&mut self, location: HexCoord, target: PlayerId) -> Result<CombatReport> {
        let player_forces: Vec<usize> = self
            .ships
            .iter()
            .filter(|s| s.location == location && s.owner == self.current_player)
            .map(|s| s.id)
            .collect();

        if player_forces.is_empty() {
            bail!(
                "You have no ships at ({}, {}) to attack with",
                location.q,
                location.r
            );
        }

        let target_forces: Vec<usize> = self
            .ships
            .iter()
            .filter(|s| s.location == location && s.owner == target)
            .map(|s| s.id)
            .collect();

        if target_forces.is_empty() {
            bail!(
                "{} has no ships at ({}, {}) to attack",
                target,
                location.q,
                location.r
            );
        }

        self.resolve_combat_between(location, self.current_player, target)
    }

    /// Roll dice for combat - each point of strength = 1d6, hits on 4+
    fn roll_combat(&self, attacker_strength: u32, defender_strength: u32) -> CombatRoll {
        let mut rng = self.rng();

        let attacker_hits = (0..attacker_strength)
            .filter(|_| rng.random_range(1..=6) >= 4)
            .count() as u32;

        let defender_hits = (0..defender_strength)
            .filter(|_| rng.random_range(1..=6) >= 4)
            .count() as u32;

        CombatRoll {
            attacker_damage: defender_hits, // Defender's hits damage attacker
            defender_damage: attacker_hits, // Attacker's hits damage defender
            attacker_hits,
            defender_hits,
        }
    }

    /// Resolve combat between two specific factions at a location
    fn resolve_combat_between(
        &mut self,
        location: HexCoord,
        attacker: PlayerId,
        defender: PlayerId,
    ) -> Result<CombatReport> {
        // Gather combat strengths
        let attacker_strength: u32 = self
            .ships
            .iter()
            .filter(|s| s.location == location && s.owner == attacker)
            .map(|s| s.ship_type.combat_strength())
            .sum();

        let defender_strength: u32 = self
            .ships
            .iter()
            .filter(|s| s.location == location && s.owner == defender)
            .map(|s| s.ship_type.combat_strength())
            .sum();

        // Add system defense for defender if they own the system
        let system_defense = self
            .systems
            .iter()
            .find(|s| s.coord == location && s.owner == Some(defender))
            .map(|s| {
                s.buildings
                    .iter()
                    .map(|b| b.building_type.defense_bonus())
                    .sum()
            })
            .unwrap_or(0);

        let total_defender_strength = defender_strength + system_defense;

        // Roll dice!
        let roll = self.roll_combat(attacker_strength, total_defender_strength);

        // Apply damage and collect casualties
        let attacker_casualties =
            self.apply_combat_damage(location, attacker, roll.defender_damage);
        let defender_casualties =
            self.apply_combat_damage(location, defender, roll.attacker_damage);

        // Collect survivors
        let attacker_survivors: Vec<ShipInfo> = self
            .ships
            .iter()
            .filter(|s| s.location == location && s.owner == attacker)
            .map(ShipInfo::from_ship)
            .collect();

        let defender_survivors: Vec<ShipInfo> = self
            .ships
            .iter()
            .filter(|s| s.location == location && s.owner == defender)
            .map(ShipInfo::from_ship)
            .collect();

        // Log the combat
        self.action_log.push(LogEntry {
            turn: self.turn,
            player: attacker,
            message: format!(
                "{} attacked {} at ({},{}) - Attacker: {} hits, Defender: {} hits",
                attacker, defender, location.q, location.r, roll.attacker_hits, roll.defender_hits
            ),
        });

        Ok(CombatReport {
            location,
            attacker,
            defender,
            attacker_strength,
            defender_strength: total_defender_strength,
            roll,
            attacker_casualties,
            defender_casualties,
            attacker_survivors,
            defender_survivors,
        })
    }

    /// Apply damage to ships at a location owned by a specific player
    /// Returns list of destroyed ship names
    fn apply_combat_damage(
        &mut self,
        location: HexCoord,
        owner: PlayerId,
        damage: u32,
    ) -> Vec<String> {
        let mut remaining_damage = damage;
        let mut casualties = Vec::new();

        // Collect ship IDs that will be damaged
        let mut ship_ids_to_damage: Vec<usize> = self
            .ships
            .iter()
            .enumerate()
            .filter(|(_, s)| s.location == location && s.owner == owner)
            .map(|(idx, _)| idx)
            .collect();

        // Sort by HP (weaker ships first)
        ship_ids_to_damage.sort_by_key(|&idx| self.ships[idx].hp);

        for &ship_idx in &ship_ids_to_damage {
            if remaining_damage == 0 {
                break;
            }

            let ship = &mut self.ships[ship_idx];
            let damage_to_ship = remaining_damage.min(ship.hp);
            ship.hp -= damage_to_ship;
            remaining_damage -= damage_to_ship;

            if ship.hp == 0 {
                casualties.push(format!("{} destroyed", ship.ship_type.name()));
            }
        }

        // Remove destroyed ships
        self.ships.retain(|s| s.hp > 0);

        casualties
    }
}

// ============================================================================
// UI STATE - Tab-based interface
// ============================================================================

use crate::game_state::GameState;
use ratatui::widgets::ListState;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum GameScreen {
    MainMenu,
    GameSetup,
    Playing,
}

#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
pub enum Tab {
    #[default]
    Galaxy,
    Ships,
    Cards,
    Systems,
}

impl Tab {
    pub fn next(&self) -> Self {
        match self {
            Tab::Galaxy => Tab::Ships,
            Tab::Ships => Tab::Cards,
            Tab::Cards => Tab::Systems,
            Tab::Systems => Tab::Galaxy,
        }
    }

    pub fn prev(&self) -> Self {
        match self {
            Tab::Galaxy => Tab::Systems,
            Tab::Ships => Tab::Galaxy,
            Tab::Cards => Tab::Ships,
            Tab::Systems => Tab::Cards,
        }
    }

    pub fn title(&self) -> &'static str {
        match self {
            Tab::Galaxy => "Galaxy Map",
            Tab::Ships => "Fleet",
            Tab::Cards => "Cards",
            Tab::Systems => "Systems",
        }
    }
}

#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
pub enum FocusMode {
    #[default]
    Map,
    Actions,
}

#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
pub enum MapMode {
    #[default]
    HexView,
    ListView,
}

#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
pub enum Modal {
    #[default]
    None,
    Help,
    QuitConfirm,
    Console,
    ShipMovement,
    Victory,
}

#[derive(Debug)]
pub struct UIState {
    pub game_screen: GameScreen,
    pub active_tab: Tab,
    pub selected_system_idx: Option<usize>,
    pub selected_ship_idx: Option<usize>,
    pub selected_card_idx: Option<usize>,
    pub action_menu_state: ListState,
    pub ship_list_state: ListState,
    pub card_list_state: ListState,
    pub system_list_state: ListState,
    pub modal: Modal,
    pub map_mode: MapMode,
    pub focus: FocusMode,
    // Movement targeting
    pub movement_target: Option<(i32, i32)>, // q, r coordinates
    // Camera controls
    pub camera_x: f64,
    pub camera_y: f64,
    pub zoom: f64,
    // Console
    pub console_input: String,
    pub console_history: Vec<String>,
    pub console_output: Vec<String>,
    pub setup_selection: usize,
    pub galaxy_size_idx: usize,
    pub num_ai_players: usize,
    pub galaxy_layout_idx: usize,
}

impl Default for UIState {
    fn default() -> Self {
        UIState::new()
    }
}

impl UIState {
    pub fn new() -> Self {
        let mut action_state = ListState::default();
        action_state.select(Some(0));

        let mut ship_state = ListState::default();
        ship_state.select(Some(0));

        let mut card_state = ListState::default();
        card_state.select(Some(0));

        let mut system_state = ListState::default();
        system_state.select(Some(0));

        Self {
            game_screen: GameScreen::MainMenu,
            active_tab: Tab::default(),
            selected_system_idx: Some(0),
            selected_ship_idx: None,
            selected_card_idx: None,
            action_menu_state: action_state,
            ship_list_state: ship_state,
            card_list_state: card_state,
            system_list_state: system_state,
            map_mode: MapMode::default(),
            focus: FocusMode::default(),
            modal: Modal::default(),
            movement_target: None,
            camera_x: 0.0,
            camera_y: 0.0,
            zoom: 1.0,
            console_input: String::new(),
            console_history: Vec::new(),
            console_output: vec!["Rhai Console - Type 'help' for commands".to_string()],
            setup_selection: 0,
            galaxy_size_idx: 1, // Medium
            num_ai_players: 2,
            galaxy_layout_idx: 0, // Clustered
        }
    }

    pub fn reset_for_new_game(&mut self) {
        self.game_screen = GameScreen::Playing;
        self.active_tab = Tab::Galaxy;
        self.selected_system_idx = Some(0);
        self.selected_ship_idx = None;
        self.selected_card_idx = None;
        self.modal = Modal::None;
        self.movement_target = None;
        self.camera_x = 0.0;
        self.camera_y = 0.0;
        self.zoom = 1.0;
        self.console_input.clear();
        self.console_output = vec!["Rhai Console - Type 'help' for commands".to_string()];
    }

    pub fn next_tab(&mut self) {
        self.active_tab = self.active_tab.next();
    }

    pub fn prev_tab(&mut self) {
        self.active_tab = self.active_tab.prev();
    }

    pub fn toggle_focus(&mut self) {
        self.focus = match self.focus {
            FocusMode::Map => FocusMode::Actions,
            FocusMode::Actions => FocusMode::Map,
        };
    }

    pub fn select_system_in_direction(&mut self, game: &GameState, dq: i32, dr: i32) {
        if let Some(current_idx) = self.selected_system_idx
            && let Some(current_system) = game.systems.get(current_idx)
        {
            let current_coord = current_system.coord;

            // Find closest system in the given direction
            let mut best_idx = current_idx;
            let mut best_distance = f64::INFINITY;

            for (idx, system) in game.systems.iter().enumerate() {
                if idx == current_idx {
                    continue;
                }

                let delta_q = system.coord.q - current_coord.q;
                let delta_r = system.coord.r - current_coord.r;

                // Check if this system is generally in the desired direction
                let dot_product = (delta_q * dq + delta_r * dr) as f64;
                if dot_product > 0.0 {
                    // Calculate actual distance
                    let distance = ((delta_q * delta_q + delta_r * delta_r) as f64).sqrt();

                    // Prefer systems more aligned with the direction
                    let alignment = dot_product / distance.max(1.0);
                    let score = distance / alignment.max(0.1);

                    if score < best_distance {
                        best_distance = score;
                        best_idx = idx;
                    }
                }
            }

            self.selected_system_idx = Some(best_idx);
        }
    }

    pub fn select_next_system(&mut self, game: &GameState) {
        if game.systems.is_empty() {
            return;
        }
        let next = match self.selected_system_idx {
            Some(i) => (i + 1) % game.systems.len(),
            None => 0,
        };
        self.selected_system_idx = Some(next);
        self.system_list_state.select(Some(next));
    }

    pub fn select_prev_system(&mut self, game: &GameState) {
        if game.systems.is_empty() {
            return;
        }
        let prev = match self.selected_system_idx {
            Some(i) => {
                if i == 0 {
                    game.systems.len() - 1
                } else {
                    i - 1
                }
            }
            None => 0,
        };
        self.selected_system_idx = Some(prev);
        self.system_list_state.select(Some(prev));
    }

    pub fn select_next_action(&mut self) {
        let i = match self.action_menu_state.selected() {
            Some(i) => (i + 1) % 4, // 4 actions available
            None => 0,
        };
        self.action_menu_state.select(Some(i));
    }

    pub fn select_prev_action(&mut self) {
        let i = match self.action_menu_state.selected() {
            Some(i) => {
                if i == 0 {
                    3
                } else {
                    i - 1
                }
            }
            None => 0,
        };
        self.action_menu_state.select(Some(i));
    }

    pub fn select_next_ship(&mut self, game: &GameState) {
        let human_ships: Vec<_> = game
            .ships
            .iter()
            .enumerate()
            .filter(|(_, s)| s.owner == crate::game_state::PlayerId::Human)
            .collect();

        if human_ships.is_empty() {
            return;
        }

        let current_pos = self.ship_list_state.selected().unwrap_or(0);
        let next = (current_pos + 1) % human_ships.len();
        self.ship_list_state.select(Some(next));
        self.selected_ship_idx = Some(human_ships[next].0);
    }

    pub fn select_prev_ship(&mut self, game: &GameState) {
        let human_ships: Vec<_> = game
            .ships
            .iter()
            .enumerate()
            .filter(|(_, s)| s.owner == crate::game_state::PlayerId::Human)
            .collect();

        if human_ships.is_empty() {
            return;
        }

        let current_pos = self.ship_list_state.selected().unwrap_or(0);
        let prev = if current_pos == 0 {
            human_ships.len() - 1
        } else {
            current_pos - 1
        };
        self.ship_list_state.select(Some(prev));
        self.selected_ship_idx = Some(human_ships[prev].0);
    }

    pub fn select_next_card(&mut self, game: &GameState) {
        if game.cards_hand.is_empty() {
            return;
        }
        let next = match self.card_list_state.selected() {
            Some(i) => (i + 1) % game.cards_hand.len(),
            None => 0,
        };
        self.card_list_state.select(Some(next));
        self.selected_card_idx = Some(next);
    }

    pub fn select_prev_card(&mut self, game: &GameState) {
        if game.cards_hand.is_empty() {
            return;
        }
        let prev = match self.card_list_state.selected() {
            Some(i) => {
                if i == 0 {
                    game.cards_hand.len() - 1
                } else {
                    i - 1
                }
            }
            None => 0,
        };
        self.card_list_state.select(Some(prev));
        self.selected_card_idx = Some(prev);
    }

    pub fn toggle_map_mode(&mut self) {
        self.map_mode = match self.map_mode {
            MapMode::HexView => MapMode::ListView,
            MapMode::ListView => MapMode::HexView,
        };
    }

    pub fn pan_camera(&mut self, dx: f64, dy: f64) {
        self.camera_x += dx;
        self.camera_y += dy;
    }

    pub fn zoom_in(&mut self) {
        self.zoom = (self.zoom * 1.2).min(3.0);
    }

    pub fn zoom_out(&mut self) {
        self.zoom = (self.zoom / 1.2).max(0.3);
    }

    pub fn reset_camera(&mut self) {
        self.camera_x = 0.0;
        self.camera_y = 0.0;
        self.zoom = 1.0;
    }
}

